package com.example.urlshortener.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.io.IOException; import java.time.Instant; import java.util.concurrent.*;
@Component public class RateLimitFilter implements Filter { private final ConcurrentHashMap<String,Window> windows=new ConcurrentHashMap<>(); @Value("${app.rate-limit-per-minute:60}") private int limit; public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException {HttpServletRequest r=(HttpServletRequest)req; HttpServletResponse h=(HttpServletResponse)res; if(!r.getRequestURI().startsWith("/api/")){chain.doFilter(req,res);return;} String key=r.getRemoteAddr(); long now=Instant.now().getEpochSecond(); Window w=windows.compute(key,(k,v)->v==null||now-v.start>=60?new Window(now,1):new Window(v.start,v.count+1)); if(w.count>limit){h.setStatus(429);h.setContentType("application/json");h.getWriter().write("{\"code\":\"RATE_LIMITED\",\"message\":\"Rate limit exceeded\"}");return;} chain.doFilter(req,res);} record Window(long start,int count){} }
